import random
def experiment(inputs):
    trials = inputs.get('trials', 200)
    window_sizes = inputs.get('window_sizes', [10, 50, 100])
    results = {}
    for window in window_sizes:
        stability = []
        for _ in range(trials):
            data = [random.uniform(0.6, 0.9) for _ in range(window)]
            stability.append(sum(data)/len(data))
        results[window] = sum(stability)/len(stability)
    return results
